/**
 * End-to-end conversion of real PDF files (generated by scripts/make-test-pdfs.py)
 * through PDF.js → layout → pipeline → markdown → chapters.
 *
 * Set DEBUG_PDF=1 to print the intermediate markdown for each fixture.
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { layoutTextItems, type PdfTextItem } from './layout';
import { runPipeline } from './pipeline';
import type { RawPage } from '@/lib/pdfExtractor';

async function loadPages(name: string): Promise<RawPage[]> {
  const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
  const file = fileURLToPath(new URL(`./__fixtures__/${name}`, import.meta.url));
  const data = new Uint8Array(readFileSync(file));
  const pdf = await pdfjs.getDocument({ data, useSystemFonts: false, isEvalSupported: false }).promise;
  const pages: RawPage[] = [];
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    const layout = layoutTextItems(content.items as PdfTextItem[]);
    pages.push({ pageNum: i, text: layout.text, headingLines: layout.headingLines });
  }
  await pdf.destroy();
  return pages;
}

async function convert(name: string) {
  const pages = await loadPages(name);
  const book = runPipeline(pages, name);
  if (process.env.DEBUG_PDF) {
    console.log(`\n===== ${name} pages =====\n${pages.map((p) => `--- p${p.pageNum}\n${p.text}`).join('\n')}`);
    console.log(`\n===== ${name} markdown =====\n${book.extraction?.markdown}`);
  }
  return book;
}

const allText = (book: Awaited<ReturnType<typeof convert>>) =>
  [book.introductionText, ...book.chapters.flatMap((c) => c.sections.map((s) => s.rawText))].join('\n');

describe('real PDF: numbered chapters with contents page', () => {
  it('finds exactly the real chapters and sections', async () => {
    const book = await convert('numbered-chapters.pdf');
    expect(book.chapters.map((c) => c.title)).toEqual(['The Pillars of Faith', 'The Pillars of Islam', 'Conclusion']);
    expect(book.chapters[0].sections.map((s) => s.title)).toEqual(['Belief in Allah', 'Belief in the Angels']);
    expect(book.chapters[1].sections.map((s) => s.title)).toEqual(['The Prayer', 'The Fast']);
  });

  it('keeps the introduction and puts content under the right chapter', async () => {
    const book = await convert('numbered-chapters.pdf');
    expect(book.introductionText).toContain('All praise is due to Allah');
    expect(book.chapters[0].sections[0].rawText).toContain('Belief in Allah includes four matters');
    expect(book.chapters[1].sections[1].rawText).toContain('Fasting the month of Ramadan');
    expect(book.chapters[2].sections[0].rawText).toContain('We ask Allah to make this treatise beneficial');
  });

  it('produces clean text: no headers, page numbers, footnote markers or broken words', async () => {
    const book = await convert('numbered-chapters.pdf');
    const text = allText(book);
    expect(text).not.toMatch(/THE FOUNDATIONS OF FAITH|SHAYKH ABDULLAH IBN AHMAD/);
    expect(text).toContain('foundation of all knowledge');
    expect(text).not.toMatch(/\. \. \./);
    // Footnote marker stays attached to its sentence; the note itself is kept separately
    expect(text).toContain('obligation upon every Muslim."[1] This narration');
    expect(text).toContain('[1] Ibn Majah, no. 224.');
    expect(text).toContain('do not disobey Him.[1]');
    expect(text).not.toMatch(/\n\d{1,2}\n/);
    expect(text).toContain('1. Belief in His existence');
  });

  it('orders the Arabic verse right-to-left', async () => {
    const book = await convert('numbered-chapters.pdf');
    expect(allText(book)).toMatch(/قل\s+هو\s+الله\s+أحد/);
  });
});

describe('real PDF: no contents page, word-numbered chapters and hadith baabs', () => {
  it('finds the two chapters with their titles and baab sections only', async () => {
    const book = await convert('no-contents.pdf');
    expect(book.chapters.map((c) => c.title)).toEqual(['Truthfulness', 'Patience']);
    expect(book.chapters[0].sections.map((s) => s.title)).toEqual([
      'What has come regarding truthfulness',
      'The reward of the truthful',
    ]);
    expect(book.chapters[1].sections).toHaveLength(2);
  });

  it('keeps numbered benefits and ALL-CAPS sources as content, not chapters', async () => {
    const book = await convert('no-contents.pdf');
    const text = allText(book);
    expect(text).toContain('SAHIH AL-BUKHARI');
    expect(text).toContain('1. The first benefit of this narration is that it encourages the believer, and it shows');
    expect(text).not.toMatch(/FORTY HADITH ON CHARACTER|IMAM AN-NAWAWI/);
  });
});

describe('real PDF: chapters that are only larger-font titles', () => {
  it('detects title chapters and their sub-headings', async () => {
    const book = await convert('titled-chapters.pdf');
    expect(book.chapters.map((c) => c.title)).toEqual(['The Book of Purification', 'The Book of Prayer']);
    expect(book.chapters[0].sections.map((s) => s.title)).toEqual(['Water and its Types', 'The Description of Ablution']);
    expect(book.chapters[1].sections.map((s) => s.title)).toEqual(['The Times of Prayer', 'The Conditions of Prayer']);
  });
});
